68	pub struct DefaultForeignCallExecutor<F> {
69	    /// The executor for any [`ForeignCall::Print`] calls.
70	    printer: Option<PrintForeignCallExecutor>,
71	    mocker: MockForeignCallExecutor<F>,
72	    external: Option<RPCForeignCallExecutor>,
73	}
74	
75	impl<F: Default> DefaultForeignCallExecutor<F> {
76	    pub fn new(
77	        show_output: bool,
78	        resolver_url: Option<&str>,
79	        root_path: Option<PathBuf>,
80	        package_name: Option<String>,
81	    ) -> Self {
82	        let id = rand::thread_rng().gen();
83	        let printer = if show_output { Some(PrintForeignCallExecutor) } else { None };
84	        let external_resolver = resolver_url.map(|resolver_url| {
85	            RPCForeignCallExecutor::new(resolver_url, id, root_path, package_name)
86	        });
87	        DefaultForeignCallExecutor {
88	            printer,
89	            mocker: MockForeignCallExecutor::default(),
90	            external: external_resolver,
91	        }
92	    }
93	}
