95	impl<F: AcirField + Serialize + for<'a> Deserialize<'a>> ForeignCallExecutor<F>
96	    for DefaultForeignCallExecutor<F>
97	{
98	    fn execute(
99	        &mut self,
100	        foreign_call: &ForeignCallWaitInfo<F>,
101	    ) -> Result<ForeignCallResult<F>, ForeignCallError> {
102	        let foreign_call_name = foreign_call.function.as_str();
103	        match ForeignCall::lookup(foreign_call_name) {
104	            Some(ForeignCall::Print) => {
105	                if let Some(printer) = &mut self.printer {
106	                    printer.execute(foreign_call)
107	                } else {
108	                    Ok(ForeignCallResult::default())
109	                }
110	            }
111	            Some(
112	                ForeignCall::CreateMock
113	                | ForeignCall::SetMockParams
114	                | ForeignCall::GetMockLastParams
115	                | ForeignCall::SetMockReturns
116	                | ForeignCall::SetMockTimes
117	                | ForeignCall::ClearMock,
118	            ) => self.mocker.execute(foreign_call),
119	
120	            None => {
121	                // First check if there's any defined mock responses for this foreign call.
122	                match self.mocker.execute(foreign_call) {
123	                    Err(ForeignCallError::NoHandler(_)) => (),
124	                    response_or_error => return response_or_error,
125	                };
126	
127	                if let Some(external_resolver) = &mut self.external {
128	                    // If the user has registered an external resolver then we forward any remaining oracle calls there.
129	                    match external_resolver.execute(foreign_call) {
130	                        Err(ForeignCallError::NoHandler(_)) => (),
131	                        response_or_error => return response_or_error,
132	                    };
133	                }
134	
135	                // If all executors have no handler for the given foreign call then we cannot
136	                // return a correct response to the ACVM. The best we can do is to return an empty response,
137	                // this allows us to ignore any foreign calls which exist solely to pass information from inside
138	                // the circuit to the environment (e.g. custom logging) as the execution will still be able to progress.
139	                //
140	                // We optimistically return an empty response for all oracle calls as the ACVM will error
141	                // should a response have been required.
142	                Ok(ForeignCallResult::default())
143	            }
144	        }
145	    }
146	}
