44	pub fn run_test<B: BlackBoxFunctionSolver<FieldElement>>(
45	    blackbox_solver: &B,
46	    context: &mut Context,
47	    test_function: &TestFunction,
48	    show_output: bool,
49	    foreign_call_resolver_url: Option<&str>,
50	    root_path: Option<PathBuf>,
51	    package_name: Option<String>,
52	    config: &CompileOptions,
53	) -> TestStatus {
54	    let test_function_has_no_arguments = context
55	        .def_interner
56	        .function_meta(&test_function.get_id())
57	        .function_signature()
58	        .0
59	        .is_empty();
60	
61	    match compile_no_check(context, config, test_function.get_id(), None, false) {
62	        Ok(compiled_program) => {
63	            if test_function_has_no_arguments {
64	                // Run the backend to ensure the PWG evaluates functions like std::hash::pedersen,
65	                // otherwise constraints involving these expressions will not error.
66	                let mut foreign_call_executor = TestForeignCallExecutor::new(
67	                    show_output,
68	                    foreign_call_resolver_url,
69	                    root_path,
70	                    package_name,
71	                );
72	
73	                let circuit_execution = execute_program(
74	                    &compiled_program.program,
75	                    WitnessMap::new(),
76	                    blackbox_solver,
77	                    &mut foreign_call_executor,
78	                );
79	
80	                let status = test_status_program_compile_pass(
81	                    test_function,
82	                    compiled_program.abi,
83	                    compiled_program.debug,
84	                    circuit_execution,
85	                );
86	
87	                let ignore_foreign_call_failures =
88	                    std::env::var("NARGO_IGNORE_TEST_FAILURES_FROM_FOREIGN_CALLS")
89	                        .is_ok_and(|var| &var == "true");
90	
91	                if let TestStatus::Fail { .. } = status {
92	                    if ignore_foreign_call_failures
93	                        && foreign_call_executor.encountered_unknown_foreign_call
94	                    {
95	                        TestStatus::Skipped
96	                    } else {
97	                        status
98	                    }
99	                } else {
100	                    status
101	                }
102	            } else {
103	                #[cfg(target_arch = "wasm32")]
104	                {
105	                    // We currently don't support fuzz testing on wasm32 as the u128 strategies do not exist on this platform.
106	                    TestStatus::Fail {
107	                        message: "Fuzz tests are not supported on wasm32".to_string(),
108	                        error_diagnostic: None,
109	                    }
110	                }
111	
112	                #[cfg(not(target_arch = "wasm32"))]
113	                {
114	                    use acvm::acir::circuit::Program;
115	                    use noir_fuzzer::FuzzedExecutor;
116	                    use proptest::test_runner::TestRunner;
117	                    let runner = TestRunner::default();
118	
119	                    let executor =
120	                        |program: &Program<FieldElement>,
121	                         initial_witness: WitnessMap<FieldElement>|
122	                         -> Result<WitnessStack<FieldElement>, String> {
123	                            execute_program(
124	                                program,
125	                                initial_witness,
126	                                blackbox_solver,
127	                                &mut TestForeignCallExecutor::<FieldElement>::new(
128	                                    false,
129	                                    foreign_call_resolver_url,
130	                                    root_path.clone(),
131	                                    package_name.clone(),
132	                                ),
133	                            )
134	                            .map_err(|err| err.to_string())
135	                        };
136	                    let fuzzer = FuzzedExecutor::new(compiled_program.into(), executor, runner);
137	
138	                    let result = fuzzer.fuzz();
