34	pub fn prepare_dependencies(
35	    context: &mut Context,
36	    parent_crate: CrateId,
37	    dependencies: &BTreeMap<CrateName, Dependency>,
38	) {
39	    for (dep_name, dep) in dependencies.iter() {
40	        match dep {
41	            Dependency::Remote { package } | Dependency::Local { package } => {
42	                let crate_id = prepare_dependency(context, &package.entry_path);
43	                add_dep(context, parent_crate, crate_id, dep_name.clone());
44	                prepare_dependencies(context, crate_id, &package.dependencies);
45	            }
46	        }
47	    }
