76	// We will pre-populate the file manager with all the files in the package
77	// This is so that we can avoid having to read from disk when we are compiling
78	//
79	// This does not require parsing because we are interested in the files under the src directory
80	// it may turn out that we do not need to include some Noir files that we add to the file
81	// manager
82	fn insert_all_files_for_package_into_file_manager(
83	    package: &Package,
84	    file_manager: &mut FileManager,
85	    overrides: &HashMap<&std::path::Path, &str>,
86	    processed_entry_paths: &mut HashSet<PathBuf>,
87	) {
88	    if processed_entry_paths.contains(&package.entry_path) {
89	        return;
90	    }
91	    processed_entry_paths.insert(package.entry_path.clone());
92	
93	    // Start off at the entry path and read all files in the parent directory.
94	    let entry_path_parent = package
95	        .entry_path
96	        .parent()
97	        .unwrap_or_else(|| panic!("The entry path is expected to be a single file within a directory and so should have a parent {:?}", package.entry_path));
98	
99	    for entry in WalkDir::new(entry_path_parent) {
100	        let Ok(entry) = entry else {
101	            continue;
102	        };
103	
104	        if !entry.file_type().is_file() {
105	            continue;
106	        }
107	
108	        if !entry.path().extension().map_or(false, |ext| ext == FILE_EXTENSION) {
109	            continue;
110	        };
111	
112	        let path = entry.into_path();
113	
114	        // Avoid reading the source if the file is already there
115	        if file_manager.has_file(&path) {
116	            continue;
117	        }
118	
119	        let source = if let Some(src) = overrides.get(path.as_path()) {
120	            src.to_string()
121	        } else {
122	            std::fs::read_to_string(path.as_path())
123	                .unwrap_or_else(|_| panic!("could not read file {:?} into string", path))
124	        };
125	
126	        file_manager.add_file_with_source(path.as_path(), source);
127	    }
128	
129	    insert_all_files_for_packages_dependencies_into_file_manager(
130	        package,
131	        file_manager,
132	        overrides,
133	        processed_entry_paths,
134	    );
135	}
