139	fn insert_all_files_for_packages_dependencies_into_file_manager(
140	    package: &Package,
141	    file_manager: &mut FileManager,
142	    overrides: &HashMap<&std::path::Path, &str>,
143	    processed_entry_paths: &mut HashSet<PathBuf>,
144	) {
145	    for (_, dep) in package.dependencies.iter() {
146	        match dep {
147	            Dependency::Local { package } | Dependency::Remote { package } => {
148	                insert_all_files_for_package_into_file_manager(
149	                    package,
150	                    file_manager,
151	                    overrides,
152	                    processed_entry_paths,
153	                );
154	            }
155	        }
156	    }
