159	pub fn parse_all(file_manager: &FileManager) -> ParsedFiles {
160	    file_manager
161	        .as_file_map()
162	        .all_file_ids()
163	        .par_bridge()
164	        .filter(|&&file_id| {
165	            let file_path = file_manager.path(file_id).expect("expected file to exist");
166	            let file_extension =
167	                file_path.extension().expect("expected all file paths to have an extension");
168	            file_extension == "nr"
169	        })
170	        .map(|&file_id| (file_id, parse_file(file_manager, file_id)))
171	        .collect()
172	}
