47	pub(crate) fn run(args: TestCommand, config: NargoConfig) -> Result<(), CliError> {
48	    let toml_path = get_package_manifest(&config.program_dir)?;
49	    let selection = args.package_options.package_selection();
50	    let workspace = resolve_workspace_from_toml(
51	        &toml_path,
52	        selection,
53	        Some(NOIR_ARTIFACT_VERSION_STRING.to_string()),
54	    )?;
55	
56	    let mut workspace_file_manager = workspace.new_file_manager();
57	    insert_all_files_for_workspace_into_file_manager(&workspace, &mut workspace_file_manager);
58	    let parsed_files = parse_all(&workspace_file_manager);
59	
60	    let pattern = match &args.test_name {
61	        Some(name) => {
62	            if args.exact {
63	                FunctionNameMatch::Exact(name)
64	            } else {
65	                FunctionNameMatch::Contains(name)
66	            }
67	        }
68	        None => FunctionNameMatch::Anything,
69	    };
70	
71	    // Configure a thread pool with a larger stack size to prevent overflowing stack in large programs.
72	    // Default is 2MB.
73	    let pool = rayon::ThreadPoolBuilder::new().stack_size(4 * 1024 * 1024).build().unwrap();
74	    let test_reports: Vec<Vec<(String, TestStatus)>> = pool.install(|| {
75	        workspace
76	            .into_iter()
77	            .par_bridge()
78	            .map(|package| {
79	                run_tests::<Bn254BlackBoxSolver>(
80	                    &workspace_file_manager,
81	                    &parsed_files,
82	                    package,
83	                    pattern,
84	                    args.show_output,
85	                    args.oracle_resolver.as_deref(),
86	                    Some(workspace.root_dir.clone()),
87	                    Some(package.name.to_string()),
88	                    &args.compile_options,
89	                )
90	            })
91	            .collect::<Result<_, _>>()
92	    })?;
93	    let test_report: Vec<(String, TestStatus)> = test_reports.into_iter().flatten().collect();
94	
95	    if test_report.is_empty() {
96	        match &pattern {
97	            FunctionNameMatch::Exact(pattern) => {
98	                return Err(CliError::Generic(
99	                    format!("Found 0 tests matching input '{pattern}'.",),
100	                ))
101	            }
102	            FunctionNameMatch::Contains(pattern) => {
103	                return Err(CliError::Generic(format!("Found 0 tests containing '{pattern}'.",)))
104	            }
105	            // If we are running all tests in a crate, having none is not an error
106	            FunctionNameMatch::Anything => {}
107	        };
108	    }
109	
110	    if test_report.iter().any(|(_, status)| status.failed()) {
111	        Err(CliError::Generic(String::new()))
112	    } else {
113	        Ok(())
114	    }
115	}
